import { merge as mainMerge } from 'es-toolkit';
import { merge as compatMerge } from 'es-toolkit/compat';

const rnd = (n) => Math.floor(Math.random() * n);
const pick = (a) => a[rnd(a.length)];
const str = () => pick(['x', 'hello', '', 'Zz9']);
const scalar = () => pick([str(), rnd(100) - 50, true, false, null, 0.5]);
const KEYS = ['a', 'b', 'c', 'd', 'size', 'theme', 'accent'];

// base generator: depth <= 3 JSON object
function genBaseObj(depth) {
  const o = {};
  const n = rnd(4);
  for (let i = 0; i < n; i++) o[pick(KEYS)] = genBaseVal(depth);
  return o;
}
function genBaseVal(depth) {
  const r = rnd(10);
  if (r < 5 || depth >= 3) return scalar();
  if (r < 7) return genBaseObj(depth + 1);
  // array: all scalars or all objects
  const n = rnd(4);
  if (rnd(2)) return Array.from({ length: n }, () => scalar());
  return Array.from({ length: n }, () => genBaseObj(depth + 1));
}
// patch generator conforming to base: overwrite same-kind slots, add new keys anywhere
function genPatch(base, depth) {
  const p = {};
  const n = rnd(4);
  for (let i = 0; i < n; i++) {
    const k = pick(KEYS);
    if (k in base) {
      const b = base[k];
      if (b !== null && typeof b === 'object' && !Array.isArray(b)) {
        if (depth < 3) p[k] = genPatch(b, depth + 1);
      } else if (Array.isArray(b)) {
        if (b.length && typeof b[0] === 'object' && b[0] !== null) {
          p[k] = Array.from({ length: rnd(3) }, () => genPatch(pick(b), depth + 1));
        } else if (b.length) {
          p[k] = Array.from({ length: rnd(3) }, () => scalar());
        }
      } else {
        p[k] = scalar();
      }
    } else {
      p[k] = genBaseVal(depth);
    }
  }
  return p;
}
const clone = (x) => JSON.parse(JSON.stringify(x));
let diffs = 0;
const N = 100000;
for (let t = 0; t < N; t++) {
  const base = genBaseObj(1);
  const patch = genPatch(base, 1);
  const a = mainMerge(clone(base), clone(patch));
  const b = compatMerge(clone(base), clone(patch));
  if (JSON.stringify(a) !== JSON.stringify(b)) {
    diffs++;
    if (diffs < 4) console.log('DIFF', JSON.stringify(base), JSON.stringify(patch), JSON.stringify(a), JSON.stringify(b));
  }
}
console.log('merge main vs compat diffs over', N, ':', diffs);
const ex = [[{}, { size: 'compact' }], [{ accent: null }, { accent: null, theme: 'blue' }]];
for (const [b, p] of ex) console.log(JSON.stringify(mainMerge(clone(b), clone(p))), JSON.stringify(compatMerge(clone(b), clone(p))));

